43: // Module is a named group of zero or more fx.Options.
44: //
45: // A Module scopes the effect of certain operations to within the module.
46: // For more information, see [Decorate], [Replace], or [Invoke].
47: //
48: // Module allows packages to bundle sophisticated functionality into easy-to-use
49: // logical units.
50: // For example, a logging package might export a simple option like this:
51: //
52: //	package logging
53: //
54: //	var Module = fx.Module("logging",
55: //		fx.Provide(func() *log.Logger {
56: //			return log.New(os.Stdout, "", 0)
57: //		}),
58: //		// ...
59: //	)
60: //
61: // A shared all-in-one microservice package could use Module to bundle
62: // all required components of a microservice:
63: //
64: //	package server
65: //
66: //	var Module = fx.Module("server",
67: //		logging.Module,
68: //		metrics.Module,
69: //		tracing.Module,
70: //		rpc.Module,
71: //	)
72: //
73: // When new global functionality is added to the service ecosystem,
74: // it can be added to the shared module with minimal churn for users.
75: //
76: // Use the all-in-one pattern sparingly.
77: // It limits the flexibility available to the application.
78: func Module(name string, opts ...Option) Option {
79: 	mo := moduleOption{
80: 		name:     name,
81: 		location: fxreflect.CallerStack(1, 2)[0],
82: 		options:  opts,
83: 	}
84: 	return mo
85: }
86: 
87: type moduleOption struct {
88: 	name     string
89: 	location fxreflect.Frame
90: 	options  []Option
91: }
92: 
93: func (o moduleOption) String() string {
94: 	return fmt.Sprintf("fx.Module(%q, %v)", o.name, o.options)
95: }
96: 
97: func (o moduleOption) apply(mod *module) {
98: 	// This get called on any submodules' that are declared
99: 	// as part of another module.
100: 
101: 	// 1. Create a new module with the parent being the specified
102: 	// module.
103: 	// 2. Apply child Options on the new module.
104: 	// 3. Append it to the parent module.
105: 
106: 	// Create trace as parent's trace with this module's location pre-pended.
107: 	trace := append([]string{fmt.Sprintf("%v (%v)", o.location, o.name)}, mod.trace...)
108: 	newModule := &module{
109: 		name:   o.name,
110: 		parent: mod,
111: 		trace:  trace,
112: 		app:    mod.app,
113: 	}
114: 	for _, opt := range o.options {
115: 		opt.apply(newModule)
116: 	}
117: 	mod.modules = append(mod.modules, newModule)
118: }
