135: // scope is a private wrapper interface for dig.Container and dig.Scope.
136: // We can consider moving this into Fx using type constraints after Go 1.20
137: // is released and 1.17 is deprecated.
138: type scope interface {
139: 	Decorate(f any, opts ...dig.DecorateOption) error
140: 	Invoke(f any, opts ...dig.InvokeOption) error
141: 	Provide(f any, opts ...dig.ProvideOption) error
142: 	Scope(name string, opts ...dig.ScopeOption) *dig.Scope
143: 	String() string
