235: func (m *module) supply(p provide) {
236: 	typeName := p.SupplyType.String()
237: 	opts := []dig.ProvideOption{
238: 		dig.Export(!p.Private),
239: 		dig.WithProviderBeforeCallback(func(bci dig.BeforeCallbackInfo) {
240: 			m.log.LogEvent(&fxevent.BeforeRun{
241: 				Name:       fmt.Sprintf("stub(%v)", typeName),
242: 				Kind:       "supply",
243: 				ModuleName: m.name,
244: 			})
245: 		}),
246: 		dig.WithProviderCallback(func(ci dig.CallbackInfo) {
247: 			m.log.LogEvent(&fxevent.Run{
248: 				Name:       fmt.Sprintf("stub(%v)", typeName),
249: 				Kind:       "supply",
250: 				Runtime:    ci.Runtime,
251: 				ModuleName: m.name,
252: 			})
253: 		}),
254: 	}
255: 
256: 	if err := runProvide(m.scope, p, opts...); err != nil {
257: 		m.app.err = err
258: 	}
259: 
260: 	m.log.LogEvent(&fxevent.Supplied{
261: 		TypeName:    typeName,
262: 		StackTrace:  p.Stack.Strings(),
263: 		ModuleTrace: append([]string{p.Stack[0].String()}, m.trace...),
264: 		ModuleName:  m.name,
265: 		Err:         m.app.err,
266: 	})
267: }
