269: // Constructs custom loggers for all modules in the tree
270: func (m *module) installAllEventLoggers() {
271: 	if m.logConstructor != nil {
272: 		if buffer, ok := m.log.(*logBuffer); ok {
273: 			// default to parent's logger if custom logger constructor fails
274: 			if err := m.installEventLogger(buffer); err != nil {
275: 				m.app.err = multierr.Append(m.app.err, err)
276: 				m.log = m.fallbackLogger
277: 				buffer.Connect(m.log)
278: 			}
279: 		}
280: 		m.fallbackLogger = nil
281: 	} else if m.parent != nil {
282: 		m.log = m.parent.log
283: 	}
284: 
285: 	for _, mod := range m.modules {
286: 		mod.installAllEventLoggers()
287: 	}
288: }
