290: func (m *module) installEventLogger(buffer *logBuffer) (err error) {
291: 	p := m.logConstructor
292: 	fname := fxreflect.FuncName(p.Target)
293: 	defer func() {
294: 		m.log.LogEvent(&fxevent.LoggerInitialized{
295: 			Err:             err,
296: 			ConstructorName: fname,
297: 		})
298: 	}()
299: 
300: 	// TODO: Use dig.FillProvideInfo to inspect the provided constructor
301: 	// and fail the application if its signature didn't match.
302: 	if err := m.scope.Provide(p.Target); err != nil {
303: 		return fmt.Errorf("fx.WithLogger(%v) from:\n%+v\nin Module: %q\nFailed: %w",
304: 			fname, p.Stack, m.name, err)
305: 	}
306: 
307: 	return m.scope.Invoke(func(log fxevent.Logger) {
308: 		m.log = log
309: 		buffer.Connect(log)
310: 	})
311: }
