335: 	err = runInvoke(m.scope, i)
336: 	m.log.LogEvent(&fxevent.Invoked{
337: 		FunctionName: fnName,
338: 		ModuleName:   m.name,
339: 		Err:          err,
340: 		Trace:        fmt.Sprintf("%+v", i.Stack), // format stack trace as multi-line
341: 	})
342: 	return err
343: }
