360: func (m *module) decorate(d decorator) (err error) {
361: 	if d.IsReplace {
362: 		return m.replace(d)
363: 	}
364: 
365: 	funcName := fxreflect.FuncName(d.Target)
366: 	var info dig.DecorateInfo
367: 	opts := []dig.DecorateOption{
368: 		dig.FillDecorateInfo(&info),
369: 		dig.WithDecoratorBeforeCallback(func(bci dig.BeforeCallbackInfo) {
370: 			m.log.LogEvent(&fxevent.BeforeRun{
371: 				Name:       funcName,
372: 				Kind:       "decorate",
373: 				ModuleName: m.name,
374: 			})
375: 		}),
376: 		dig.WithDecoratorCallback(func(ci dig.CallbackInfo) {
377: 			m.log.LogEvent(&fxevent.Run{
378: 				Name:       funcName,
379: 				Kind:       "decorate",
380: 				ModuleName: m.name,
381: 				Runtime:    ci.Runtime,
382: 				Err:        ci.Error,
383: 			})
384: 		}),
385: 	}
386: 
387: 	err = runDecorator(m.scope, d, opts...)
388: 	outputNames := make([]string, len(info.Outputs))
389: 	for i, o := range info.Outputs {
390: 		outputNames[i] = o.String()
391: 	}
392: 
393: 	m.log.LogEvent(&fxevent.Decorated{
