30: )
31: 
32: // Provide registers any number of constructor functions, teaching the
33: // application how to instantiate various types. The supplied constructor
34: // function(s) may depend on other types available in the application, must
35: // return one or more objects, and may return an error. For example:
36: //
37: //	// Constructs type *C, depends on *A and *B.
38: //	func(*A, *B) *C
39: //
40: //	// Constructs type *C, depends on *A and *B, and indicates failure by
41: //	// returning an error.
42: //	func(*A, *B) (*C, error)
43: //
44: //	// Constructs types *B and *C, depends on *A, and can fail.
45: //	func(*A) (*B, *C, error)
46: //
47: // The order in which constructors are provided doesn't matter, and passing
48: // multiple Provide options appends to the application's collection of
49: // constructors. Constructors are called only if one or more of their returned
50: // types are needed, and their results are cached for reuse (so instances of a
51: // type are effectively singletons within an application). Taken together,
52: // these properties make it perfectly reasonable to Provide a large number of
53: // constructors even if only a fraction of them are used.
54: //
55: // See the documentation of the In and Out types for advanced features,
56: // including optional parameters and named instances.
57: //
58: // See the documentation for [Private] for restricting access to constructors.
59: //
60: // Constructor functions should perform as little external interaction as
61: // possible, and should avoid spawning goroutines. Things like server listen
62: // loops, background timer loops, and background processing goroutines should
63: // instead be managed using Lifecycle callbacks.
64: func Provide(constructors ...any) Option {
65: 	return provideOption{
66: 		Targets: constructors,
67: 		Stack:   fxreflect.CallerStack(1, 0),
68: 	}
69: }
70: 
71: type provideOption struct {
72: 	Targets []any
73: 	Stack   fxreflect.Stack
74: }
75: 
76: func (o provideOption) apply(mod *module) {
77: 	var private bool
78: 
79: 	targets := make([]any, 0, len(o.Targets))
80: 	for _, target := range o.Targets {
81: 		if _, ok := target.(privateOption); ok {
82: 			private = true
83: 			continue
84: 		}
85: 		targets = append(targets, target)
86: 	}
87: 
88: 	for _, target := range targets {
89: 		mod.provides = append(mod.provides, provide{
90: 			Target:  target,
91: 			Stack:   o.Stack,
92: 			Private: private,
93: 		})
94: 	}
95: }
96: 
97: type privateOption struct{}
98: 
99: // Private is an option that can be passed as an argument to [Provide] or [Supply] to
100: // restrict access to the constructors being provided. Specifically,
101: // corresponding constructors can only be used within the current module
102: // or modules the current module contains. Other modules that contain this
103: // module won't be able to use the constructor.
104: //
105: // For example, the following would fail because the app doesn't have access
106: // to the inner module's constructor.
107: //
108: //	fx.New(
109: //		fx.Module("SubModule", fx.Provide(func() int { return 0 }, fx.Private)),
110: //		fx.Invoke(func(a int) {}),
111: //	)
112: var Private = privateOption{}
113: 
114: func (o provideOption) String() string {
115: 	items := make([]string, len(o.Targets))
116: 	for i, c := range o.Targets {
117: 		items[i] = fxreflect.FuncName(c)
118: 	}
119: 	return fmt.Sprintf("fx.Provide(%s)", strings.Join(items, ", "))
120: }
121: 
122: func runProvide(c container, p provide, opts ...dig.ProvideOption) error {
123: 	constructor := p.Target
124: 	if _, ok := constructor.(Option); ok {
125: 		return fmt.Errorf("fx.Option should be passed to fx.New directly, "+
126: 			"not to fx.Provide: fx.Provide received %v from:\n%+v",
127: 			constructor, p.Stack)
128: 	}
129: 
130: 	switch constructor := constructor.(type) {
131: 	case annotationError:
132: 		// fx.Annotate failed. Turn it into an Fx error.
133: 		return fmt.Errorf(
134: 			"encountered error while applying annotation using fx.Annotate to %s: %w",
135: 			fxreflect.FuncName(constructor.target), constructor.err)
136: 
137: 	case annotated:
138: 		ctor, err := constructor.Build()
139: 		if err != nil {
140: 			return fmt.Errorf("fx.Provide(%v) from:\n%+vFailed: %w", constructor, p.Stack, err)
141: 		}
142: 
143: 		opts = append(opts, dig.LocationForPC(constructor.FuncPtr))
144: 		if err := c.Provide(ctor, opts...); err != nil {
145: 			return fmt.Errorf("fx.Provide(%v) from:\n%+vFailed: %w", constructor, p.Stack, err)
146: 		}
147: 
148: 	case Annotated:
149: 		ann := constructor
150: 		switch {
151: 		case len(ann.Group) > 0 && len(ann.Name) > 0:
152: 			return fmt.Errorf(
153: 				"fx.Annotated may specify only one of Name or Group: received %v from:\n%+v",
154: 				ann, p.Stack)
155: 		case len(ann.Name) > 0:
156: 			opts = append(opts, dig.Name(ann.Name))
157: 		case len(ann.Group) > 0:
158: 			opts = append(opts, dig.Group(ann.Group))
159: 		}
160: 
161: 		if err := c.Provide(ann.Target, opts...); err != nil {
162: 			return fmt.Errorf("fx.Provide(%v) from:\n%+vFailed: %w", ann, p.Stack, err)
163: 		}
164: 
165: 	default:
166: 		if reflect.TypeOf(constructor).Kind() == reflect.Func {
167: 			ft := reflect.ValueOf(constructor).Type()
168: 
169: 			for i := 0; i < ft.NumOut(); i++ {
170: 				t := ft.Out(i)
171: 
172: 				if t == reflect.TypeOf(Annotated{}) {
173: 					return fmt.Errorf(
174: 						"fx.Annotated should be passed to fx.Provide directly, "+
175: 							"it should not be returned by the constructor: "+
176: 							"fx.Provide received %v from:\n%+v",
177: 						fxreflect.FuncName(constructor), p.Stack)
178: 				}
179: 			}
180: 		}
181: 
182: 		if err := c.Provide(constructor, opts...); err != nil {
183: 			return fmt.Errorf("fx.Provide(%v) from:\n%+vFailed: %w", fxreflect.FuncName(constructor), p.Stack, err)
184: 		}
185: 	}
186: 	return nil
187: }

